INSERT INTO scenario (scenario_key, title, tagline, genre, protagonist_id, slice_end_day, cold_open, goal, deadline_day) VALUES
('mystery', 'Who Burned the Mill?', 'Nobody burns a village. A village burns itself, one whisper at a time.', 'Mystery', 11, 4, 'Day 12. Dusk. The commons is full.
INSERT INTO case_link (link_key, scenario_key, title, question, ord) VALUES
('motive', 'mystery', 'Motive', 'Why would anyone kill Tobin?', 1),
('means', 'mystery', 'Means', 'Who had the hand to do it?', 2),
('meeting', 'mystery', 'Meeting', 'Who met Tobin that night?', 3),
('murder', 'mystery', 'Murder', 'How did Tobin die?', 4),
('match', 'mystery', 'Match', 'Who lit the fire?', 5),
('mask', 'mystery', 'Mask', 'Who built the frame around you?', 6),
('master', 'mystery', 'Master', 'Who is behind all of it?', 7);
INSERT INTO clue (clue_key, scenario_key, title, kind, day, journal) VALUES
('C01', 'mystery', 'Wick''s ink-dark fingertips', 'observation', 1, 'As Old Wick took the cup from you, you noticed his fingertips were stained nearly black, the way they are every day. He makes his own ink from walnut husks.'),
('C02', 'mystery', 'The packet''s seal', 'observation', 1, 'The packet Wick gave you for Ines is sealed with wax pressed from a tiny well-bucket. It is not the seal of any office you know.'),
('C17', 'mystery', 'The drover''s grey horse', 'observation', 1, 'The drover lodging at the inn rides a grey horse. Under the saddle blanket you glimpsed a brand: a crowned R. It means nothing to you yet.'),
('C04', 'mystery', 'Voices at the well-house', 'observation', 2, 'After dark you heard Tobin and Old Wick arguing inside the well-house. Tobin said, ''Tomorrow night, after the bell, at the mill. Bring the seal.'' Wick said he would.'),
('C25', 'mystery', 'Thorn''s threat', 'rumour', 3, 'In the square, Garth Thorn shouted that Tobin''s grain prices would ruin the valley, and that he would see the mill burn before he paid them. Everyone heard.'),
('C05u', 'mystery', 'A folded page (unread)', 'document', 3, 'Tobin pressed a folded page into your hand and told you to show no one. You have not read it.'),
('C05', 'mystery', 'Page 41', 'document', 3, 'Page 41 of Tobin''s ledger, a copy of a land survey. In the margin, in Tobin''s hand: ''E. has sold us. The survey is false. Midnight, the mill, bring the seal.'' Who is E.?'),
('C14b', 'mystery', 'Two men at the mill''s back door', 'observation', 3, 'From the alder hedge you saw two men go in at the mill''s back door a little before eleven. One carried a green-glass lantern. You did not see the second man''s face.'),
('C07', 'mystery', 'Tobin''s stopped watch', 'physical', 4, 'On the office floor lay Tobin''s watch, glass smashed, stopped at twenty to twelve. The fire did not start until midnight.'),
('C09', 'mystery', 'The strongbox', 'physical', 4, 'The mill''s strongbox was open and empty. The lock had been cut from the outside, and the cut is clean. Before the fire, not by it.'),
('C08', 'mystery', 'Tobin''s wound', 'physical', 4, 'Tobin''s head was split above the ear. A fire does not do that. He was dead before the smoke reached him.'),
('C10', 'mystery', 'Far too much oil', 'physical', 4, 'The cellar stones are slick with oil. A pint can lit the grain shed, and nothing more. This was gallons, poured on purpose.'),
('C13', 'mystery', 'Lily saw Wick pick up a key', 'testimony', 4, 'Lily says that on the day Tobin shouted at you, she saw Old Wick take something shiny off the well hook and put it in his pocket. She thought it was a key.'),
('C03a', 'mystery', 'The well lantern was dark', 'testimony', 4, 'Lily says the well lantern, which Old Wick lights every night of his life, was dark the night of the fire. (He may have an explanation.)');
