INSERT INTO story_day (scenario_key, day, title, intro, outro) VALUES
('mystery', 1, 'Day 1 · A grey morning', 'Ten years ago you came to Alderbrook with nothing but your name. The Hollis family took you in. Today their kitchen is quiet, and the debt is louder than the rain. Tobin owes you a wage that never comes full, and the Reeve visits in twelve days. Three things you can do today. Choose carefully: nothing in Alderbrook is ever small.', 'Night settles on Alderbrook. Out at the inn the drover''s grey horse is saddled and gone, and Ines says only that he rides at night and she does not ask. You lie awake wondering who a stranger rides to, in a village this small.'),
('mystery', 2, 'Day 2 · Heat', 'By noon the whole square has heard Tobin''s voice. You have never known him to shout. Something has got into him, and into the village.', 'Long after the village sleeps, Tobin''s lamp is still burning at the mill. He is not shouting any more. Tomorrow he will be worse: quiet. You cannot shake the feeling that he is saying goodbye to something.'),
('mystery', 3, 'Day 3 · The quiet', 'Tobin does not shout today. That is worse. He moves about the mill like a man counting his steps.', 'A little after midnight the mill bell starts to ring, and it does not stop. Your window has turned orange. By the time you are on the stairs you already know which building is burning.'),
('mystery', 4, 'Day 4 · Ashes', 'The mill is a black tooth at the end of the lane. Smoke still leans over the valley. Somewhere in the ruin is a man you have worked beside for four years.', 'By dusk the ruins are cold. Pike''s colours are on the north road, one day out. And Giles has still not come home.');
INSERT INTO story_beat (beat_key, scenario_key, day, phase, ord, title, body, costs_action, max_picks, requires_beats, forbids_beats, focus) VALUES
('d1_well', 'mystery', 1, 'morning', 0, 'The well', 'Old Wick is at the well, as he is every morning. He taught you your letters when you were eleven and silent as a stone. He lifts the bucket and a tin cup and beckons. ''Sit, lad. Everyone who drinks from this well owes it a story.''', TRUE, 1, '{}'::text[], '{}'::text[], 'well'),
('d1_packet', 'mystery', 1, 'day', 1, 'A small errand', 'Wick presses a small sealed packet into your hand. ''Would you take this to Ines at the inn? My knees are not what they were. It is only herbs for her cough.'' The wax is the colour of old honey.', TRUE, 1, '{}'::text[], '{}'::text[], 'inn'),
('d1_giles', 'mystery', 1, 'day', 2, 'Giles asks for a coin', 'Your foster-brother Giles, sixteen and furious at everything, catches your sleeve outside the Hollis gate. ''Lend me a coin, Ro. Just one. Ma needs a lamp for the cellar and the chandler won''t give credit.'' He will not meet your eyes.', TRUE, 1, '{}'::text[], '{}'::text[], 'Hollis'),
('d1_inn', 'mystery', 1, 'day', 3, 'The inn', 'A drover has taken the corner table at Ines''s inn. He is a large, quiet man with good boots, and a grey horse stands outside with a saddle blanket folded over the rail. ''Lodging since dawn,'' Ines murmurs. ''Pays in silver.''', TRUE, 1, '{}'::text[], '{}'::text[], 'inn'),
('d1_tobin', 'mystery', 1, 'day', 4, 'Pay day', 'Tobin counts coins into your palm at the mill door and stops one coin short. He will not look at you. ''The mill is running at a loss, Rowan. I am sorry.''', TRUE, 1, '{}'::text[], '{}'::text[], 'mill'),
('d2_quarrel', 'mystery', 2, 'day', 5, 'In the square', 'It happens at noon, in front of seven villagers. Tobin, who has never raised his voice to you, accuses you of selling flour on the side. ''Someone told me. Someone I trust.'' The square is silent. Everyone is looking at you.', FALSE, 1, '{}'::text[], '{}'::text[], 'market'),
('d2_home', 'mystery', 2, 'day', 6, 'The Hollis kitchen', 'Bethan is coughing again. Giles sits on the stairs with his chin on his knees. Milo is drawing the mill in the ash of the hearth. Nobody asks about the square. Everybody already knows.', TRUE, 1, '{}'::text[], '{}'::text[], 'Hollis'),
('d2_maren', 'mystery', 2, 'day', 7, 'Maren''s kitchen', 'Maren feeds you before you can say a word. She is the warmest woman in Alderbrook, and the bakery smells of everything good. ''Tell me,'' she says. ''Tell Maren.''', TRUE, 1, '{}'::text[], '{}'::text[], 'bakery'),
('d2_night', 'mystery', 2, 'night', 8, 'A restless night', 'You cannot sleep. The well-house stands dark at the edge of the lane, and a thin line of light shows under its door. Someone is awake in there.', TRUE, 1, '{}'::text[], '{}'::text[], 'well'),
('d3_page', 'mystery', 3, 'day', 9, 'Closing time', 'At closing, Tobin takes you aside, over a bowl of soup you did not ask for. ''The commons can''t be sold without the seal of the whole Moot,'' he says, almost to himself. ''Not the Reeve, not the Crown. Every voice in the valley. That is older than any Reeve.'' Then he presses a folded page into your hand. ''Keep this safe. If anything happens to me, show it to no one in Alderbrook.''', FALSE, 1, '{}'::text[], '{}'::text[], 'mill'),
('d3_read_later', 'mystery', 3, 'day', 10, 'The page, again', 'The folded page is warm against your ribs. You have not looked.', TRUE, 1, ARRAY['d3_page:pocket']::text[], '{}'::text[], 'Hollis'),
('d3_hide', 'mystery', 3, 'day', 11, 'Where to hide it', 'You cannot carry it everywhere, and you cannot leave it lying about. Whoever it names will want it, and so, perhaps, will whoever wrote the survey.', TRUE, 1, ARRAY['d3_page']::text[], '{}'::text[], 'Hollis'),
('d3_tell', 'mystery', 3, 'day', 12, 'Someone to tell', 'A secret this size is heavy. You could tell someone, and you will have to choose who.', TRUE, 1, ARRAY['d3_page:read_now']::text[], '{}'::text[], 'bakery'),
('d3_night', 'mystery', 3, 'night', 13, 'After the bell', 'Tobin told you to stay home tonight, and not to come to the mill at dawn. But he has been strange for days, and you have been Tobin''s helper for four years. A little before eleven you stand at the Hollis gate, looking at the lane.', TRUE, 1, '{}'::text[], '{}'::text[], 'mill'),
('d4_fire', 'mystery', 4, 'morning', 14, 'The bell', 'You wake to the bell and the glow in the window. The mill is burning. You run. You have three moves before the roof comes down, and the smoke is already in your lungs. Every move costs you breath.', FALSE, 3, '{}'::text[], ARRAY['d3_night:go_to_mill']::text[], 'mill'),
('d4_wake', 'mystery', 4, 'morning', 15, 'A ringing head', 'You wake in a ditch behind the alder hedge with the sky grey and bitter with smoke. Your head is split and your clothes are wet with dew. The mill is gone. The village is gathering, and no one can say where you were.', FALSE, 1, ARRAY['d3_night:go_to_mill']::text[], '{}'::text[], 'mill'),
('d4_wick', 'mystery', 4, 'morning', 16, 'Old Wick speaks', 'Garth Thorn demands a rope. The crowd roars. Then Old Wick steps forward and raises a hand, and the noise falls. ''Give the boy a fair week,'' he says. ''The Reeve comes on the twelfth. If he is guilty, the law will find it.'' He looks at you, and for a moment he is only an old man who is sorry.', FALSE, 1, '{}'::text[], '{}'::text[], 'well'),
('d4_ruins', 'mystery', 4, 'day', 17, 'The ruins', 'Pike''s deputies have not come yet, and the ruins are cooling. If there is anything to find in the black stones, it will not be there tomorrow.', TRUE, 1, '{}'::text[], '{}'::text[], 'mill'),
('d4_lily', 'mystery', 4, 'day', 18, 'Lily on the wall', 'Ines''s niece, Lily, ten years old, is sitting on the well wall with her knees drawn up. She has been there since dawn. Everyone has walked past her. She is watching you.', TRUE, 1, '{}'::text[], '{}'::text[], 'well'),
('d4_home', 'mystery', 4, 'day', 19, 'The Hollis house', 'Bethan is white-faced at the table. Milo has not spoken since dawn. Giles did not come home last night, and nobody knows where he is.', TRUE, 1, '{}'::text[], '{}'::text[], 'Hollis');
INSERT INTO story_option (beat_key, option_key, label, result_text, ord, react_actor, react_line) VALUES
('d1_well', 'share_loaf', 'Share your breakfast loaf with him', 'He takes the bread with both hands like it is something precious. ''You have a kind face,'' he says. ''That is a dangerous thing to wear in a place like this.'' He tells you the story of the river that changed its mind about where to run, and how everything in the valley moved to follow it. ''A village is only ever the shape of its water.''', 0, 1, 'You have a kind face, lad.'),
('d1_well', 'listen', 'Sit and listen to his story', 'He tells it slowly: the river that changed its mind, and the valley that had to follow. ''The Moot meets on the commons,'' he adds lightly, ''and always has. It is the one thing in this valley nobody owns.'' He hands you the cup. You drink.', 1, 1, 'Sit. Everyone owes the well a story.'),
('d1_well', 'skip', 'Wave and hurry on', 'He lifts the cup in salute and lets you go. ''Another day, lad.'' You feel his eyes on your back all the way down the lane.', 2, 1, 'Another day, lad.'),
('d1_packet', 'carry', 'Carry it to Ines, no questions', 'Ines takes the packet without looking at it, as if she has done this before, and tucks it behind the bar. ''Tell him thanks.''', 0, 8, 'Tell him thanks.'),
('d1_packet', 'peek', 'Carry it, and look closely at the seal', 'On the way you turn it in the light. The seal is a tiny well-bucket pressed into wax. It is not the mark of any office you know. Ines takes it from you without a word, and your neck prickles; she has done this before.', 1, 8, 'You did not need to look.'),
('d1_packet', 'refuse', 'Say you are busy', '''Of course, lad.'' He is not offended. Within the hour you see Ines''s niece hurry past with it in her apron. It reached her anyway.', 2, 1, 'Of course, lad.'),
('d1_giles', 'give', 'Give him a coin', 'He closes his hand around it. ''Thanks. I will not forget this.'' He runs off toward the chandler''s.', 0, 13, 'Thanks. I will not forget this.'),
('d1_giles', 'give_two', 'Give him two', '''Two?'' He stares, then grins in spite of himself. ''You are a good brother.'' You do not feel good. You feel watched.', 1, 13, 'Two? You are a good brother.'),
('d1_giles', 'refuse', 'Tell him you cannot spare it', '''Of course you cannot.'' His face closes like a door. By evening you see him at the well with Old Wick, and Wick''s hand on his shoulder. Whatever he needed, he got.', 2, 13, 'Of course you cannot.'),
('d1_inn', 'cup', 'Take a cup and pass the time', 'The drover nods and says nothing. You hear the horse stamp outside. Ines refills your cup unasked.', 0, NULL, NULL),
('d1_inn', 'look_close', 'Look closely at the horse', 'While the drover is turned away you lift the corner of the blanket. Under the saddle, burned into the leather: a crowned R. You let the blanket fall. When you look up, the drover is watching you.', 1, NULL, NULL),
('d1_tobin', 'accept', 'Accept it quietly', '''You are a good worker,'' he says, and means it. It does not feel like enough.', 0, 5, 'You are a good worker.'),
('d1_tobin', 'ask', 'Ask what is wrong', 'He sighs. ''The Hollis ledger is behind, thirty crowns, and the Reeve comes on the twelfth. I cannot carry it forever. I did not want to tell you.'' Thirty crowns. The Hollis house. Giles. Bethan. You, with them.', 1, 5, 'I did not want to tell you.'),
('d1_tobin', 'push', 'Push back: you earned it', 'His jaw sets. ''Mind yourself.'' Two of the other labourers hear. Word travels.', 2, 5, 'Mind yourself.'),
('d2_quarrel', 'apologise', 'Say nothing. Apologise for the misunderstanding', 'You keep your voice level. ''I have never taken a grain.'' Some people look away. Tobin looks ashamed. It helps, a little.', 0, 5, '...I should not have shouted.'),
('d2_quarrel', 'defend', 'Defend yourself loudly', 'You shout back that you have bled for that mill. The crowd murmurs. The words feel like the wrong ones as soon as they leave you.', 1, 5, 'Someone told me. Someone I trust.'),
('d2_quarrel', 'counter', 'Accuse him of shorting your wages', 'A gasp goes round the square. Tobin goes grey. A boy at the back whispers ''bad blood'' and no one stops him.', 2, 5, '...'),
('d2_home', 'comfort_giles', 'Sit with Giles', '''I do not want to lose the house,'' he says to the floor. ''Not because of the ledger. Because of what they say about you.'' It is the longest he has spoken in a month.', 0, 13, 'I do not want to lose the house.'),
('d2_home', 'ask_bethan', 'Ask Bethan about the debt', 'She tells you all of it, in a voice worn thin. Thirty crowns. A debt to the mill. ''Tobin has been good to us,'' she says. ''Do not think badly of him.''', 1, NULL, NULL),
('d2_home', 'chores', 'Do the evening chores', 'You split wood until your hands are raw. It helps. For an hour you do not think.', 2, NULL, NULL),
('d2_maren', 'confide', 'Tell her everything about the quarrel', 'She listens, her hand over yours. ''He is under a strain. Leave it with me.'' It is the first time all day you feel held. You do not notice her glance at the door.', 0, 2, 'Leave it with me, love.'),
('d2_maren', 'deflect', 'Say it is nothing', '''If you say so, love.'' She wraps a loaf for you anyway. She does not look convinced.', 1, 2, 'If you say so, love.'),
('d2_night', 'watch_wellhouse', 'Creep to the well-house and listen', 'Two voices. Tobin, low and hard: ''Tomorrow night, after the bell, at the mill. Bring the seal.'' And a gentle, tired voice you would know anywhere. ''I will, Tobin. I will.'' You back away before the door opens.', 0, NULL, NULL),
('d2_night', 'inn', 'Walk to the inn for a quiet drink', 'Ines is wiping the bar. The drover is gone. His horse is still in the stable. ''He rides out at night,'' she says, ''and I do not ask.''', 1, NULL, NULL),
('d2_night', 'sleep', 'Go to bed', 'You sleep badly and dream of fire. You have always dreamed of fire.', 2, NULL, NULL),
('d3_page', 'read_now', 'Unfold it and read it', 'It is page 41 of the mill ledger, a copy of a land survey. In the margin, in Tobin''s hand: ''E. has sold us. The survey is false. Midnight, the mill, bring the seal.'' Your mouth goes dry. Who is E.?', 0, NULL, NULL),
('d3_page', 'pocket', 'Put it away unread', 'You tuck it into your shirt without looking. You do not know why your hands are shaking.', 1, NULL, NULL),
('d3_read_later', 'read', 'Read it now', 'Page 41 of the mill ledger, a copy of a land survey. In the margin, in Tobin''s hand: ''E. has sold us. The survey is false. Midnight, the mill, bring the seal.'' Who is E.?', 0, NULL, NULL),
('d3_hide', 'room', 'Under the loose board in your room', 'A bare board and a thin hope. It is the first place anyone would look.', 0, NULL, NULL),
('d3_hide', 'oven', 'In Maren''s oven flue', 'Warm, dry, and in the one house you trust. The flue is cold at night. You pray she does not light it.', 1, NULL, NULL),
('d3_hide', 'well', 'Down in the stones of the well', 'Nobody goes into the well but the keeper. You push the page behind a loose stone with a coil of twine. It feels safe, somehow, and foolish.', 2, NULL, NULL),
('d3_hide', 'person', 'Keep it on your body', 'It crackles against your ribs when you breathe. If anyone searches you, there is nowhere to hide.', 3, NULL, NULL),
('d3_tell', 'elspeth', 'Tell Elspeth, Maren''s helper and your oldest friend', 'Her eyes go round. ''E.?'' she says. ''E. for what?'' She swears on her mother''s grave to say nothing. You believe her.', 0, 3, 'E.? E. for what?'),
('d3_tell', 'maren', 'Tell Maren', 'She goes very still. ''Oh, love.'' Her hands shake as she pours your tea. ''Say nothing to anybody else.'' She holds you a moment too long.', 1, 2, 'Say nothing to anybody else.'),
('d3_tell', 'nobody', 'Tell no one', 'The silence is heavy and clean. You will carry this alone.', 2, NULL, NULL),
('d3_night', 'stay_home', 'Do as he said. Stay home', 'You lie awake until the clock strikes twelve. Then you hear the bell.', 0, NULL, NULL),
('d3_night', 'go_to_mill', 'Go to the mill anyway', 'You slip through the alder hedge behind the mill. A little before eleven two men come along the path. One carries a lantern with green glass. They go in at the back door and do not light the office. You edge closer to hear. Something hits you from behind and the night goes out.', 1, NULL, NULL),
('d4_fire', 'office', 'Force the back door and go for the office', 'Heat like a wall. In the office the floor is littered with burning paper. On the boards lies Tobin''s watch, its glass smashed, stopped at twenty to twelve. The strongbox gapes open and empty. The lock has been cut from outside. You stagger back, choking.', 0, NULL, NULL),
('d4_fire', 'body', 'Drag Tobin''s body out', 'You find him by the cellar stairs. His head is split above the ear. You get your arms under his and haul. The villagers see you come out of the smoke, covered in soot and blood, carrying a dead man. You will not be able to explain that.', 1, NULL, NULL),
('d4_fire', 'grain', 'Save what you can from the grain store', 'You and Garth Thorn''s men beat back the flames from the grain store with wet sacks. Thorn claps you on the shoulder, breathing hard. It is the first time he has looked at you as a person.', 2, NULL, NULL),
('d4_fire', 'alarm', 'Stay back and raise the alarm', 'You ring the chapel bell until your arms burn. You are not in the fire. You are not anywhere you should not be. Whatever you could have found in the mill, you will never know.', 3, NULL, NULL),
('d4_wake', 'go', 'Stagger toward the smoke', 'By the time you reach the lane, half the village has seen you come out of the hedge, hatless, bloody, and an hour late. ''That is him,'' someone says. You hear it.', 0, NULL, NULL),
('d4_wick', 'listen', 'Thank him with your eyes', 'He nods, almost imperceptibly. You feel the crowd settle. It is the first kind thing anyone has done for you all morning.', 0, 1, 'Give the boy a fair week.'),
('d4_wick', 'watch', 'Watch his hands as he speaks', 'His fingers are clasped in front of him. They are as black as ever. They are perfectly steady. You do not know why you noticed.', 1, NULL, NULL),
('d4_ruins', 'cellar', 'Search the cellar', 'The stones are slick and the smell is wrong. This is not grain oil. It is lamp oil, gallons of it, soaked into the floor. A pint can lit the grain shed and nothing more.', 0, NULL, NULL),
('d4_ruins', 'strongbox', 'Look at the strongbox', 'Open and empty. The lock has been cut from the outside, and the cut is clean. Before the fire, not by it.', 1, NULL, NULL),
('d4_lily', 'gentle', 'Sit beside her and ask gently', 'She is quiet a long time. Then, very small: ''The well was dark the night of the fire. Old Wick always lights the lantern. And on the day Mr Tobin shouted at you, I saw Old Wick take something shiny off the hook. I thought it was a key.'' She does not look at you. ''Nobody asks me.''', 0, 10, 'Nobody asks me.'),
('d4_lily', 'press', 'Press her hard: what did she see?', 'She goes white and puts her hands over her ears. ''Go away.'' Two women nearby look at you the way you hoped nobody would.', 1, 10, 'Go away.'),
('d4_home', 'reassure', 'Sit with Bethan and promise to find him', 'She grips your hand. ''He is a good boy. He is only frightened.'' You say it back to her. You do not know if it is true.', 0, 12, 'He is only frightened.'),
('d4_home', 'search', 'Go looking for Giles at once', 'You search the lane, the barn, the chandler''s. No sign. A neighbour says she saw a lad running toward Hartley Farm before dawn.', 1, NULL, NULL);
INSERT INTO story_ending (scenario_key, ending_key, title, text, flag) VALUES
('mystery', 'smoke', 'The Smoke Takes You', 'You went back for one more thing. The roof came down. The last thing you see is the bell rope burning above you. In the morning, the village will say that Rowan Hollis died in the fire he set. You will not be there to say otherwise.', 'dead');
