('story_start', NULL, '{"action":"state_change","actor":null,"payload":{"entity_id":11,"set":{"coins":6,"mood":"curious","suspicion":0,"danger":0,"smoke":0,"stealth":0,"misdirect":0,"trust_wick":30,"trust_maren":30,"trust_tobin":30,"trust_giles":30,"trust_ines":20,"trust_elspeth":30,"trust_thorn":0,"trust_lily":10,"trust_bethan":40}},"visibility":"private"}', NULL, 0),
('story_start', '{"trait":"kind"}', '{"action":"state_change","actor":null,"payload":{"entity_id":11,"add":{"trust_wick":10,"trust_maren":10,"trust_tobin":10,"trust_giles":10,"trust_ines":10,"trust_elspeth":10,"trust_bethan":10}},"visibility":"private"}', NULL, 0),
('story_start', '{"trait":"sharp"}', '{"action":"state_change","actor":null,"payload":{"entity_id":11,"set":{"press_bonus":1}},"visibility":"private"}', NULL, 0),
('story_start', '{"trait":"quiet"}', '{"action":"state_change","actor":null,"payload":{"entity_id":11,"set":{"stealth":1}},"visibility":"private"}', NULL, 0),
