('day_start', '{"scenario":"mystery","payload_eq":{"day":1}}', '{"action":"story_event","actor":1,"payload":{"kind":"wick_plan","text":"Old Wick watches the Hollis house from the well, and counts the days to the Reeve."},"visibility":"private"}', NULL, 0),
